 6→export function Providers({children}: { children: React.ReactNode }) {
 7→    const [queryClient] = useState(
 8→        () =>
 9→            new QueryClient({
10→                defaultOptions: {
11→                    queries: {
12→                        staleTime: 30 * 1000, // 30 seconds
13→                        refetchOnWindowFocus: false,
14→                    },
