117→// ========================================
118→// Add Dictionary Dialog
119→// ========================================
120→
121→interface AddDictionaryDialogProps {
122→    open: boolean;
123→    onOpenChange: (open: boolean) => void;
124→    type: DictionaryType;
125→}
126→
127→export function AddDictionaryDialog({open, onOpenChange, type}: AddDictionaryDialogProps) {
128→    const category = getCategory(type);
129→    const createMutation = useCreateDictionary();
130→
131→    // Form state
132→    const [keyword, setKeyword] = useState("");
133→    const [value, setValue] = useState("");
134→    const [synonymDirection, setSynonymDirection] = useState<'bidirectional' | 'unidirectional'>('bidirectional');
135→
136→    // Validation
137→    const [errors, setErrors] = useState<string[]>([]);
138→
139→    // Reset form when dialog opens
140→    useEffect(() => {
141→        if (open) {
142→            setKeyword("");
143→            setValue("");
144→            setSynonymDirection('bidirectional');
145→            setErrors([]);
146→        }
147→    }, [open]);
148→
149→    const validate = (): boolean => {
150→        const newErrors: string[] = [];
151→
152→        if (category === 'SET') {
153→            if (!value.trim()) {
154→                newErrors.push("단어를 입력해주세요.");
155→            }
156→        } else if (category === 'SYNONYM') {
157→            if (type === 'SYNONYM') {
158→                if (synonymDirection === 'bidirectional') {
159→                    const synonyms = parseCommaSeparated(value);
160→                    if (synonyms.length < 2) {
161→                        newErrors.push("양방향 동의어는 최소 2개 이상 입력해주세요.");
162→                    }
163→                } else {
164→                    if (!keyword.trim()) {
165→                        newErrors.push("대표 단어를 입력해주세요.");
166→                    }
167→                    if (!value.trim()) {
168→                        newErrors.push("동의어 목록을 입력해주세요.");
169→                    }
170→                    // Check for self-loop
171→                    const synonyms = parseCommaSeparated(value);
172→                    if (synonyms.includes(keyword.trim())) {
173→                        newErrors.push("대표 단어가 동의어 목록에 포함될 수 없습니다.");
174→                    }
175→                }
176→            } else {
177→                // UNIT_SYNONYM
178→                if (!keyword.trim()) {
179→                    newErrors.push("대상 표현을 입력해주세요.");
180→                }
181→                if (!value.trim()) {
182→                    newErrors.push("정규화 기호를 입력해주세요.");
183→                }
184→            }
185→        } else if (category === 'MAP') {
186→            if (!keyword.trim()) {
187→                newErrors.push(type === 'SPACE' ? "붙여쓴 말을 입력해주세요." : "복합어를 입력해주세요.");
188→            }
189→            if (type === 'SPACE' && keyword.includes(' ')) {
190→                newErrors.push("붙여쓴 말에는 공백이 포함될 수 없습니다.");
191→            }
192→            if (!value.trim()) {
193→                newErrors.push(type === 'SPACE' ? "분리 결과를 입력해주세요." : "분해 결과를 입력해주세요.");
194→            }
195→            const parts = parseCommaSeparated(value);
196→            if (parts.length < 2) {
197→                newErrors.push("결과는 최소 2개 이상의 단어여야 합니다.");
198→            }
199→        }
200→
201→        setErrors(newErrors);
202→        return newErrors.length === 0;
203→    };
204→
205→    const handleSubmit = async () => {
206→        if (!validate()) return;
207→
208→        try {
209→            let finalKeyword: string | null = null;
210→            let finalValue: string | null = null;
211→
212→            if (category === 'SET') {
213→                // SET types (STOP, USER, ENGLISH, UNIT) store word in keyword field
214→                finalKeyword = value.trim();
215→                finalValue = null;
216→            } else if (category === 'SYNONYM') {
217→                if (type === 'SYNONYM' && synonymDirection === 'bidirectional') {
218→                    finalKeyword = null;
219→                } else {
220→                    finalKeyword = keyword.trim();
221→                }
222→                finalValue = value.trim();
223→            } else if (category === 'MAP') {
224→                finalKeyword = keyword.trim();
225→                finalValue = value.trim();
226→            }
227→
228→            await createMutation.mutateAsync({
229→                type,
230→                keyword: finalKeyword,
231→                value: finalValue,
232→            });
233→
234→            toast.success("사전이 추가되었습니다.");
235→            onOpenChange(false);
236→        } catch (error) {
237→            toast.error("추가 중 오류가 발생했습니다.");
238→        }
239→    };
240→
241→    return (
242→        <Dialog open={open} onOpenChange={onOpenChange}>
243→            <DialogContent className="sm:max-w-[500px]">
244→                <DialogHeader>
245→                    <DialogTitle>{getTypeLabel(type)} 사전 추가</DialogTitle>
246→                    <DialogDescription>
247→                        새로운 {getTypeLabel(type)} 항목을 추가합니다.
248→                    </DialogDescription>
249→                </DialogHeader>
250→
251→                <div className="space-y-4 py-4">
252→                    {/* SET Type Form */}
253→                    {category === 'SET' && (
254→                        <div className="space-y-2">
255→                            <Label htmlFor="value">단어 *</Label>
256→                            <Input
257→                                id="value"
258→                                value={value}
259→                                onChange={(e) => setValue(e.target.value)}
260→                                placeholder={
261→                                    type === 'ENGLISH' ? "예: hello" :
262→                                        type === 'UNIT' ? "예: kg, cm" :
263→                                            "예: 그러나, 하지만"
264→                                }
265→                            />
266→                            <p className="text-xs text-muted-foreground">
267→                                <Info className="inline h-3 w-3 mr-1"/>
268→                                단순 키워드 등록 - 분석 시 해당 단어로 인식됩니다
269→                            </p>
270→                        </div>
271→                    )}
272→
273→                    {/* SYNONYM Type Form */}
274→                    {type === 'SYNONYM' && (
275→                        <>
276→                            <div className="space-y-3">
277→                                <Label>매핑 방향</Label>
278→                                <RadioGroup
279→                                    value={synonymDirection}
280→                                    onValueChange={(v) => setSynonymDirection(v as 'bidirectional' | 'unidirectional')}
281→                                    className="flex flex-col space-y-2"
282→                                >
283→                                    <div className="flex items-center space-x-2">
284→                                        <RadioGroupItem value="bidirectional" id="bidirectional"/>
285→                                        <Label htmlFor="bidirectional" className="font-normal flex items-center gap-2">
286→                                            <ArrowLeftRight className="h-4 w-4 text-blue-500"/>
287→                                            양방향 (상호 동의어)
288→                                        </Label>
289→                                    </div>
290→                                    <div className="flex items-center space-x-2">
291→                                        <RadioGroupItem value="unidirectional" id="unidirectional"/>
292→                                        <Label htmlFor="unidirectional" className="font-normal flex items-center gap-2">
293→                                            <ArrowRight className="h-4 w-4 text-green-500"/>
294→                                            단방향 (대표어 → 동의어)
295→                                        </Label>
296→                                    </div>
297→                                </RadioGroup>
298→                            </div>
299→
300→                            <Separator/>
301→
302→                            {synonymDirection === 'bidirectional' ? (
303→                                <div className="space-y-2">
304→                                    <Label htmlFor="synonyms">동의어 그룹 *</Label>
305→                                    <Input
306→                                        id="synonyms"
307→                                        value={value}
308→                                        onChange={(e) => setValue(e.target.value)}
309→                                        placeholder="노트북, 랩탑, 휴대용컴퓨터"
310→                                    />
311→                                    <p className="text-xs text-muted-foreground">
