454→interface EditDictionaryDialogProps {
455→    open: boolean;
456→    onOpenChange: (open: boolean) => void;
457→    type: DictionaryType;
458→    item: Dictionary | null;
459→}
460→
461→export function EditDictionaryDialog({open, onOpenChange, type, item}: EditDictionaryDialogProps) {
462→    const category = getCategory(type);
463→    const updateMutation = useUpdateDictionary();
464→
465→    // Form state
466→    const [keyword, setKeyword] = useState("");
467→    const [value, setValue] = useState("");
468→    const [synonymDirection, setSynonymDirection] = useState<'bidirectional' | 'unidirectional'>('bidirectional');
469→
470→    // Validation
471→    const [errors, setErrors] = useState<string[]>([]);
472→
473→    // Initialize form when item changes
474→    useEffect(() => {
475→        if (item) {
476→            setKeyword(item.keyword || "");
477→            // SET types store word in keyword field, other types use value
478→            if (category === 'SET') {
479→                setValue(item.keyword || "");
480→            } else {
481→                setValue(item.value || "");
482→            }
483→            setSynonymDirection(item.keyword === null ? 'bidirectional' : 'unidirectional');
484→            setErrors([]);
485→        }
486→    }, [item, category]);
487→
488→    const validate = (): boolean => {
489→        const newErrors: string[] = [];
490→
491→        if (category === 'SET') {
492→            if (!value.trim()) {
493→                newErrors.push("단어를 입력해주세요.");
494→            }
495→        } else if (category === 'SYNONYM') {
496→            if (type === 'SYNONYM') {
497→                if (synonymDirection === 'bidirectional') {
498→                    const synonyms = parseCommaSeparated(value);
499→                    if (synonyms.length < 2) {
500→                        newErrors.push("양방향 동의어는 최소 2개 이상 입력해주세요.");
501→                    }
502→                } else {
503→                    if (!keyword.trim()) {
504→                        newErrors.push("대표 단어를 입력해주세요.");
505→                    }
506→                    if (!value.trim()) {
507→                        newErrors.push("동의어 목록을 입력해주세요.");
508→                    }
509→                    const synonyms = parseCommaSeparated(value);
510→                    if (synonyms.includes(keyword.trim())) {
511→                        newErrors.push("대표 단어가 동의어 목록에 포함될 수 없습니다.");
512→                    }
513→                }
514→            } else {
515→                if (!keyword.trim()) {
516→                    newErrors.push("대상 표현을 입력해주세요.");
517→                }
518→                if (!value.trim()) {
519→                    newErrors.push("정규화 기호를 입력해주세요.");
520→                }
521→            }
522→        } else if (category === 'MAP') {
523→            if (!keyword.trim()) {
524→                newErrors.push(type === 'SPACE' ? "붙여쓴 말을 입력해주세요." : "복합어를 입력해주세요.");
525→            }
526→            if (type === 'SPACE' && keyword.includes(' ')) {
527→                newErrors.push("붙여쓴 말에는 공백이 포함될 수 없습니다.");
528→            }
529→            if (!value.trim()) {
530→                newErrors.push(type === 'SPACE' ? "분리 결과를 입력해주세요." : "분해 결과를 입력해주세요.");
531→            }
532→            const parts = parseCommaSeparated(value);
533→            if (parts.length < 2) {
534→                newErrors.push("결과는 최소 2개 이상의 단어여야 합니다.");
535→            }
536→        }
537→
538→        setErrors(newErrors);
539→        return newErrors.length === 0;
540→    };
541→
542→    const handleSubmit = async () => {
543→        if (!item || !validate()) return;
544→
545→        try {
546→            let finalKeyword: string | null = null;
547→            let finalValue: string | null = null;
548→
549→            if (category === 'SET') {
550→                // SET types (STOP, USER, ENGLISH, UNIT) store word in keyword field
551→                finalKeyword = value.trim();
552→                finalValue = null;
553→            } else if (category === 'SYNONYM') {
554→                if (type === 'SYNONYM' && synonymDirection === 'bidirectional') {
555→                    finalKeyword = null;
556→                } else {
557→                    finalKeyword = keyword.trim();
558→                }
559→                finalValue = value.trim();
560→            } else if (category === 'MAP') {
561→                finalKeyword = keyword.trim();
562→                finalValue = value.trim();
563→            }
564→
565→            await updateMutation.mutateAsync({
566→                type,
567→                id: item.id,
568→                keyword: finalKeyword,
569→                value: finalValue,
570→            });
571→
572→            toast.success("사전이 수정되었습니다.");
573→            onOpenChange(false);
574→        } catch (error) {
575→            toast.error("수정 중 오류가 발생했습니다.");
576→        }
577→    };
578→
579→    if (!item) return null;
580→
581→    return (
582→        <Dialog open={open} onOpenChange={onOpenChange}>
583→            <DialogContent className="sm:max-w-[500px]">
584→                <DialogHeader>
585→                    <DialogTitle>{getTypeLabel(type)} 사전 수정</DialogTitle>
586→                    <DialogDescription>
587→                        기존 {getTypeLabel(type)} 항목을 수정합니다.
588→                    </DialogDescription>
589→                </DialogHeader>
590→
591→                <div className="space-y-4 py-4">
592→                    {/* SET Type Form */}
593→                    {category === 'SET' && (
594→                        <div className="space-y-2">
595→                            <Label htmlFor="value">단어 *</Label>
596→                            <Input
597→                                id="value"
598→                                value={value}
599→                                onChange={(e) => setValue(e.target.value)}
600→                            />
601→                        </div>
602→                    )}
603→
604→                    {/* SYNONYM Type Form */}
605→                    {type === 'SYNONYM' && (
606→                        <>
607→                            <div className="space-y-3">
608→                                <Label>매핑 방향</Label>
609→                                <RadioGroup
610→                                    value={synonymDirection}
611→                                    onValueChange={(v) => setSynonymDirection(v as 'bidirectional' | 'unidirectional')}
612→                                    className="flex flex-col space-y-2"
613→                                >
614→                                    <div className="flex items-center space-x-2">
615→                                        <RadioGroupItem value="bidirectional" id="edit-bidirectional"/>
616→                                        <Label htmlFor="edit-bidirectional"
617→                                               className="font-normal flex items-center gap-2">
618→                                            <ArrowLeftRight className="h-4 w-4 text-blue-500"/>
619→                                            양방향 (상호 동의어)
620→                                        </Label>
621→                                    </div>
622→                                    <div className="flex items-center space-x-2">
623→                                        <RadioGroupItem value="unidirectional" id="edit-unidirectional"/>
624→                                        <Label htmlFor="edit-unidirectional"
625→                                               className="font-normal flex items-center gap-2">
626→                                            <ArrowRight className="h-4 w-4 text-green-500"/>
627→                                            단방향 (대표어 → 동의어)
628→                                        </Label>
629→                                    </div>
630→                                </RadioGroup>
631→                            </div>
632→
633→                            <Separator/>
634→
635→                            {synonymDirection === 'bidirectional' ? (
636→                                <div className="space-y-2">
637→                                    <Label htmlFor="edit-synonyms">동의어 그룹 *</Label>
638→                                    <Input
639→                                        id="edit-synonyms"
640→                                        value={value}
641→                                        onChange={(e) => setValue(e.target.value)}
642→                                    />
643→                                </div>
644→                            ) : (
645→                                <>
646→                                    <div className="space-y-2">
647→                                        <Label htmlFor="edit-keyword">대표 단어 *</Label>
648→                                        <Input
649→                                            id="edit-keyword"
650→                                            value={keyword}
651→                                            onChange={(e) => setKeyword(e.target.value)}
652→                                        />
653→                                    </div>
654→                                    <div className="space-y-2">
655→                                        <Label htmlFor="edit-synonymValue">동의어 목록 *</Label>
656→                                        <Input
657→                                            id="edit-synonymValue"
658→                                            value={value}
659→                                            onChange={(e) => setValue(e.target.value)}
660→                                        />
661→                                    </div>
662→                                </>
663→                            )}
664→
665→                            <SynonymPreview
666→                                direction={synonymDirection}
667→                                keyword={keyword}
668→                                value={value}
669→                            />
670→                        </>
671→                    )}
672→
673→                    {/* UNIT_SYNONYM Type Form */}
674→                    {type === 'UNIT_SYNONYM' && (
675→                        <>
676→                            <div className="space-y-2">
677→                                <Label htmlFor="edit-unit-keyword">대상 표현 *</Label>
678→                                <Input
679→                                    id="edit-unit-keyword"
680→                                    value={keyword}
681→                                    onChange={(e) => setKeyword(e.target.value)}
682→                                />
683→                            </div>
684→                            <div className="space-y-2">
685→                                <Label htmlFor="edit-unit-value">정규화 기호 *</Label>
686→                                <Input
687→                                    id="edit-unit-value"
688→                                    value={value}
689→                                    onChange={(e) => setValue(e.target.value)}
690→                                />
691→                            </div>
692→                        </>
693→                    )}
694→
695→                    {/* MAP Type Form */}
696→                    {category === 'MAP' && (
697→                        <>
698→                            <div className="space-y-2">
699→                                <Label htmlFor="edit-map-keyword">
700→                                    {type === 'SPACE' ? '붙여쓴 말' : '복합어'} *
701→                                </Label>
702→                                <Input
703→                                    id="edit-map-keyword"
704→                                    value={keyword}
705→                                    onChange={(e) => setKeyword(e.target.value)}
706→                                />
707→                            </div>
708→                            <div className="space-y-2">
709→                                <Label htmlFor="edit-map-value">
