200→// ========================================
201→// Dictionary Compile Hook
202→// ========================================
203→
204→interface CompileDictionaryParams {
205→    types: DictionaryType[];
206→}
207→
208→export function useCompileDictionary() {
209→    const queryClient = useQueryClient();
210→
211→    return useMutation({
212→        mutationFn: async (params: CompileDictionaryParams): Promise<CompileResult[]> => {
213→            const {types} = params;
214→
215→            // If all 8 types are selected, use the bulk compile endpoint
216→            if (types.length === 8) {
217→                const response = await apiClient.post<CompileResult[]>(
218→                    '/api/v1/dictionary/compile'
219→                );
220→                return response.data;
221→            }
222→
223→            // Otherwise, compile each type individually in parallel
224→            const results = await Promise.all(
225→                types.map(async (type) => {
226→                    const response = await apiClient.post<CompileResult>(
227→                        `/api/v1/dictionary/compile/${type}`
228→                    );
229→                    return response.data;
230→                })
231→            );
232→            return results;
233→        },
234→        onSuccess: () => {
235→            // Invalidate overview to refresh lastModified times
236→            queryClient.invalidateQueries({
237→                queryKey: analysisKeys.dictionaryOverview(),
238→            });
239→        },
240→    });
241→}
