 26→export function DictionaryOverview() {
 27→    const [selectedTypes, setSelectedTypes] = useState<DictionaryType[]>([]);
 28→
 29→    const {data, isLoading, isError, refetch} = useDictionaryOverview();
 30→    const compileMutation = useCompileDictionary();
 31→
 32→    const items = data?.items || [];
 33→
 34→    // 타입 순서대로 정렬된 아이템
 35→    const sortedItems = DICTIONARY_TYPE_ORDER.map((type) =>
 36→        items.find((item) => item.type === type)
 37→    ).filter(Boolean);
 38→
 39→    const allTypesSelected = selectedTypes.length === DICTIONARY_TYPE_ORDER.length;
 40→    const someTypesSelected = selectedTypes.length > 0 && !allTypesSelected;
 41→
 42→    const toggleSelectAll = (checked: boolean) => {
 43→        if (checked) {
 44→            setSelectedTypes([...DICTIONARY_TYPE_ORDER]);
 45→        } else {
 46→            setSelectedTypes([]);
 47→        }
 48→    };
 49→
 50→    const toggleSelectType = (type: DictionaryType, checked: boolean) => {
 51→        if (checked) {
 52→            setSelectedTypes((prev) => [...prev, type]);
 53→        } else {
 54→            setSelectedTypes((prev) => prev.filter((t) => t !== type));
