 62→    const [currentCursor, setCurrentCursor] = useState<string | null>(null);
 63→    const [cursorHistory, setCursorHistory] = useState<(string | null)[]>([null]); // Stack of cursors for "previous" navigation
 64→    const [currentPage, setCurrentPage] = useState(1); // For display purposes only
 65→
 66→    // Active search (only updates on Enter or button click)
 67→    const [activeSearch, setActiveSearch] = useState("");
 68→
 69→    const category = DICTIONARY_CATEGORY_MAP[type];
 70→
 71→    // API hooks
 72→    const {data, isLoading, isError, refetch} = useDictionaries({
 73→        type,
 74→        cursor: currentCursor,
 75→        pageSize,
