 86→    const hasNext = data?.hasNext || false;
 87→    const nextCursor = data?.nextCursor || null;
 88→    const hasPrevious = cursorHistory.length > 1;
 89→
 90→    // Reset to first page
 91→    const resetPagination = () => {
 92→        setCurrentCursor(null);
 93→        setCursorHistory([null]);
 94→        setCurrentPage(1);
 95→    };
 96→
 97→    const handleSearch = () => {
 98→        resetPagination();
