117→        if (hasNext && nextCursor) {
118→            setCursorHistory((prev) => [...prev, nextCursor]);
119→            setCurrentCursor(nextCursor);
120→            setCurrentPage((prev) => prev + 1);
121→        }
122→    };
123→
124→    // Navigate to previous page
125→    const handlePreviousPage = () => {
126→        if (hasPrevious) {
127→            const newHistory = [...cursorHistory];
128→            newHistory.pop(); // Remove current cursor
129→            const previousCursor = newHistory[newHistory.length - 1];
130→            setCursorHistory(newHistory);
131→            setCurrentCursor(previousCursor);
