  1→"use client";
  2→
  3→import {useEffect, useState} from "react";
  4→import {
  5→    Dialog,
  6→    DialogContent,
  7→    DialogDescription,
  8→    DialogFooter,
  9→    DialogHeader,
 10→    DialogTitle,
 11→} from "@/components/ui/dialog";
 12→import {Button} from "@/components/ui/button";
 13→import {Input} from "@/components/ui/input";
 14→import {Label} from "@/components/ui/label";
 15→import {RadioGroup, RadioGroupItem} from "@/components/ui/radio-group";
 16→import {Badge} from "@/components/ui/badge";
 17→import {Separator} from "@/components/ui/separator";
 18→import {Alert, AlertDescription} from "@/components/ui/alert";
 19→import {AlertCircle, ArrowLeftRight, ArrowRight, Info, Loader2,} from "lucide-react";
 20→import {useCreateDictionary, useUpdateDictionary} from "@/hooks/use-dictionary";
 21→import type {Dictionary, DictionaryCategory, DictionaryType} from "@/types";
 22→import {DICTIONARY_CATEGORY_MAP, DICTIONARY_TYPE_LABELS} from "@/types";
 23→import {toast} from "sonner";
 24→
 25→// ========================================
 26→// Helper Functions
 27→// ========================================
 28→
 29→function getCategory(type: DictionaryType): DictionaryCategory {
 30→    return DICTIONARY_CATEGORY_MAP[type];
 31→}
 32→
 33→function getTypeLabel(type: DictionaryType): string {
 34→    return DICTIONARY_TYPE_LABELS[type];
 35→}
 36→
 37→function parseCommaSeparated(value: string): string[] {
 38→    return value.split(',').map(v => v.trim()).filter(Boolean);
 39→}
 40→
 41→// ========================================
 42→// Preview Components
 43→// ========================================
 44→
 45→interface SynonymPreviewProps {
 46→    direction: 'bidirectional' | 'unidirectional';
 47→    keyword: string;
 48→    value: string;
 49→}
 50→
 51→function SynonymPreview({direction, keyword, value}: SynonymPreviewProps) {
 52→    const synonyms = parseCommaSeparated(value);
 53→
 54→    if (synonyms.length === 0) return null;
 55→
 56→    return (
 57→        <div className="p-3 bg-muted/50 rounded-lg text-sm space-y-2">
 58→            <p className="font-medium text-muted-foreground">적용 미리보기</p>
 59→            {direction === 'bidirectional' ? (
 60→                <div className="space-y-1">
 61→                    {synonyms.slice(0, 2).map((word, i) => (
 62→                        <p key={i} className="text-xs">
 63→                            &quot;{word}&quot; 검색 → {synonyms.map((s, j) => (
 64→                            <Badge key={j} variant="secondary" className="mx-0.5 text-xs">{s}</Badge>
 65→                        ))} 결과
 66→                        </p>
 67→                    ))}
 68→                </div>
 69→            ) : (
 70→                <div className="space-y-1">
 71→                    <p className="text-xs">
 72→                        {synonyms.map((s, i) => (
 73→                            <span key={i}>&quot;{s}&quot;{i < synonyms.length - 1 ? ', ' : ''}</span>
 74→                        ))} 검색 → &quot;{keyword}&quot;로 인식
 75→                    </p>
 76→                    <p className="text-xs text-muted-foreground">
 77→                        &quot;{keyword}&quot; 검색 → &quot;{keyword}&quot;만 결과 (역방향 X)
 78→                    </p>
 79→                </div>
 80→            )}
 81→        </div>
 82→    );
 83→}
 84→
 85→interface MapPreviewProps {
 86→    type: DictionaryType;
 87→    keyword: string;
 88→    value: string;
 89→}
 90→
 91→function MapPreview({type, keyword, value}: MapPreviewProps) {
 92→    const parts = parseCommaSeparated(value);
 93→
 94→    if (!keyword || parts.length === 0) return null;
 95→
 96→    return (
 97→        <div className="p-3 bg-muted/50 rounded-lg text-sm space-y-2">
 98→            <p className="font-medium text-muted-foreground">
 99→                {type === 'SPACE' ? '변환' : type === 'COMPOUND' ? '색인' : '변환'} 미리보기
100→            </p>
101→            <div className="space-y-1">
102→                <p className="text-xs">
103→                    &quot;{keyword}&quot; → {parts.map((p, i) => (
104→                    <Badge key={i} variant="secondary" className="mx-0.5 text-xs">{p}</Badge>
105→                ))}
106→                </p>
107→                {type === 'COMPOUND' && (
108→                    <p className="text-xs text-muted-foreground">
109→                        &quot;{parts[0]}&quot; 검색 → &quot;{keyword}&quot; 문서도 검색 가능
110→                    </p>
111→                )}
112→            </div>
113→        </div>
114→    );
115→}
